  (1526, $$Debería haber sabido que no debía acercarme tanto a Buenos Aires por la noche.$$, $$Mi esposa y yo llegamos a Buenos Aires a plena luz del día.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1527, $$Los pensamientos de Bouchard alternaban entre esta y otras cosas mientras estaba ahí, en el sofá cama.$$, $$Bouchard tuvo un sueño irreflexivo en su lecho diurno.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1529, $$Los pensamientos de Bouchard alternaban entre esta y otras cosas mientras estaba ahí, en el sofá cama.$$, $$Bouchard pensaba mucho en la última vez que vio a su madre.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1530, $$Pero esto no es Inglaterra, señora. Se escuchó el rugido de una segunda arma, y un disparo redondo salpicó el agua a menos de la mitad de la longitud de un cable a popa.$$, $$Nuestro bote navegó pacíficamente cerca de las costas de Inglaterra.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1531, $$Pero esto no es Inglaterra, señora. Se escuchó el rugido de una segunda arma, y un disparo redondo salpicó el agua a menos de la mitad de la longitud de un cable a popa.$$, $$Los piratas estaban atacando el barco para capturar a la princesa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1533, $$Sí, claro, se lo diré.$$, $$Bien entonces, te lo contaré.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1534, $$Sí, claro, se lo diré.$$, $$No te diré una palabra.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1535, $$Sí, claro, se lo diré.$$, $$Es sólo porque prometiste no repetir esto por lo que te lo estoy diciendo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1546, $$Tus motivos fueron sin duda dignos... tu gratitud hacia él por librarte de los españoles.$$, $$Los españoles planearon lanzarte por la borda durante la noche.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1548, $$¿Por qué dejaste ir a López y a los demás? Gritó con un toque de amargura.$$, $$Había dejado ir a López, pero se quedó con los demás.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1549, $$¿Por qué dejaste ir a López y a los demás? Gritó con un toque de amargura.$$, $$López fue prisionero durante tres días.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1550, $$¿Por qué dejaste ir a López y a los demás? Gritó con un toque de amargura.$$, $$López no fue la única persona que se fue.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1551, $$Es esa maldita enagua que te hace cobarde.$$, $$Las enaguas se consideran malditas porque a menudo mienten.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1553, $$Es esa maldita enagua que te hace cobarde.$$, $$Sos bastante valiente gracias a las enaguas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1554, $$¡Ah!$$, $$Alguien está preguntando a dónde ir.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1555, $$¡Ah!$$, $$El que pregunta está solo y no tiene a nadie cerca para consultar.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1556, $$¡Ah!$$, $$El que pregunta tiene prisa y necesita saber de inmediato la ruta a seguir.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1559, $$González lo arrancó de un tirón, con un juramento.$$, $$González solo siguió mirándole, sin moverse.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1560, $$No concedo la comisión al Rey a la ligera.$$, $$Otorgar la comisión del Rey va en contra de mis principios morales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1562, $$No concedo la comisión al Rey a la ligera.$$, $$Firmé la orden para conceder la comisión del Rey sin pensarlo dos veces.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1563, $$Se dio cuenta de que tendría que retirarse a toda prisa.$$, $$Se dio cuenta de que tenía todo el día para estar retirado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1564, $$Se dio cuenta de que tendría que retirarse a toda prisa.$$, $$Se dio cuenta de que tenía que hacer un movimiento rápido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1565, $$Se dio cuenta de que tendría que retirarse a toda prisa.$$, $$Si se quedaba en el mismo lugar, sería descubierto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1566, $$Incluso ahora Bouchard no se percató.$$, $$Bouchard ha estado muy interesado en eso desde septiembre.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1567, $$Incluso ahora Bouchard no se percató.$$, $$Incluso ahora Bouchard no tuvo ojos para eso$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1569, $$Y, sin embargo, ha sido lo que ha sido y ha hecho lo que ha hecho en estos tres años, dijo ella. Pero ahora lo dijo con tristeza, sin ninguno de sus desprecios anteriores.$$, $$A ella no le gustó que hubiera asesinado a muchos hombres en los últimos tres años.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1570, $$Y, sin embargo, ha sido lo que ha sido y ha hecho lo que ha hecho en estos tres años, dijo ella. Pero ahora lo dijo con tristeza, sin ninguno de sus desprecios anteriores.$$, $$Ella habló felizmente de sus aventuras y su personalidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1571, $$Y, sin embargo, ha sido lo que ha sido y ha hecho lo que ha hecho en estos tres años, dijo ella. Pero ahora lo dijo con tristeza, sin ninguno de sus desprecios anteriores.$$, $$Ella habló con tonos tristes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1572, $$Supongo que eso es, según la moda de tu clase.$$, $$Supongo que esto es lo que hacen los de tu tipo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1574, $$Supongo que eso es, según la moda de tu clase.$$, $$Supongo que esto no es común entre los de tu clase.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1575, $$Tiene el ceño fruncido.$$, $$Una gran sonrisa se extendió en su rostro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1576, $$Tiene el ceño fruncido.$$, $$Sintió una sensación de náusea en el estómago.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1577, $$Tiene el ceño fruncido.$$, $$Estaba frunciendo el ceño.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1578, $$Ella lo había estado observando con ojos brillantes, pero a la vista de su rostro abatido y el ceño fruncido que le marcaba la frente, su propia expresión cambió.$$, $$Su expresión cambió después de ver su rostro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1579, $$Ella lo había estado observando con ojos brillantes, pero a la vista de su rostro abatido y el ceño fruncido que le marcaba la frente, su propia expresión cambió.$$, $$Su cara se iluminó cuando vio el ceño fruncido en su cara.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1580, $$Ella lo había estado observando con ojos brillantes, pero a la vista de su rostro abatido y el ceño fruncido que le marcaba la frente, su propia expresión cambió.$$, $$No sabía si él estaba enojado con ella.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1581, $$Caminando tranquilamente, bordeó la pared asediada, y atravesó las grandes puertas hacia el patio.$$, $$Como las grandes puertas estaban cerradas con llave, saltó la valla, al patio.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1582, $$Caminando tranquilamente, bordeó la pared asediada, y atravesó las grandes puertas hacia el patio.$$, $$Las grandes puertas eran la única entrada al patio.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1583, $$Caminando tranquilamente, bordeó la pared asediada, y atravesó las grandes puertas hacia el patio.$$, $$Había grandes puertas que daban al patio.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1584, $$Diga que espero con ansias conocerlo ahí. CAPÍTULO XXII.$$, $$Diga que no tengo ganas de encontrarlo ahí.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1585, $$Diga que espero con ansias conocerlo ahí. CAPÍTULO XXII.$$, $$Dígale que espero verlo ahí esta tarde.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1586, $$Diga que espero con ansias conocerlo ahí. CAPÍTULO XXII.$$, $$Diga que espero con ansias encontrarlo ahí.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1587, $$Seguro que lo llevás a la horca, dijo con desdeño.$$, $$Pensó que alguien iría al patíbulo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1588, $$Seguro que lo llevás a la horca, dijo con desdeño.$$, $$Él era un alguacil que había capturado a un ladrón.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1589, $$Seguro que lo llevás a la horca, dijo con desdeño.$$, $$Susurra una manera de escapar del país para evitar la cárcel.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1590, $$Creo que fue la esperanza de atrapar y colgar al Capitán Bouchard lo que hizo que mi tío dejase sus plantaciones en Barbados y aceptase el gobierno suplente de Buenos Aires.$$, $$Creo que mi tío quería que el Capitán Bouchard muriese por sus crímenes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1591, $$Creo que fue la esperanza de atrapar y colgar al Capitán Bouchard lo que hizo que mi tío dejase sus plantaciones en Barbados y aceptase el gobierno suplente de Buenos Aires.$$, $$Mi tío dejó sus plantaciones de Barbados antes de aceptar un puesto en Buenos Aires.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1592, $$Creo que fue la esperanza de atrapar y colgar al Capitán Bouchard lo que hizo que mi tío dejase sus plantaciones en Barbados y aceptase el gobierno suplente de Buenos Aires.$$, $$Mi tío solía amar al Capitán Bouchard y nunca dejó sus plantaciones en Barbados.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1593, $$¿Cómo podría honestamente haberlos detenido? Fue en el trato.$$, $$No tuve el valor de detenerles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1594, $$¿Cómo podría honestamente haberlos detenido? Fue en el trato.$$, $$Los detuve tan pronto los vi.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1595, $$¿Cómo podría honestamente haberlos detenido? Fue en el trato.$$, $$No me habría perdonado a mí mismo si los hubiera detenido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1596, $$Se ha informado al Coronel Rodríguez de mi llegada. El cambio repentino en los modales de Calderón con la mención del nombre de San Martín demostró que había recibido la notificación y que tenía conocimiento de la misma.$$, $$Tanto Coronel Rodríguez como Calderón fueron notificados de mi llegada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1597, $$Se ha informado al Coronel Rodríguez de mi llegada. El cambio repentino en los modales de Calderón con la mención del nombre de San Martín demostró que había recibido la notificación y que tenía conocimiento de la misma.$$, $$El Coronel Rodríguez y Calderón se sorprendieron cuando mencionaron mi nombre.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1598, $$Se ha informado al Coronel Rodríguez de mi llegada. El cambio repentino en los modales de Calderón con la mención del nombre de San Martín demostró que había recibido la notificación y que tenía conocimiento de la misma.$$, $$Cabalgué hacia Rodríguez y Calderón a caballo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1602, $$Lo estuve buscando este año pasado.$$, $$Lo estuve siguiendo de cerca durante un año sin que él lo supiera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1603, $$Lo estuve buscando este año pasado.$$, $$Solo lo he estado siguiendo durante una semana.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1605, $$En ese momento se abrió un camino entre las filas de hombres, y a través de él vino la señorita Rodríguez seguida por su ochavona.$$, $$La señorita Rodríguez caminó a través de un grupo de hombres.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1616, $$Podés estar en lo cierto, y podés estar equivocado.$$, $$Podés estar equivocado, pero también es posible que estés en lo cierto$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1617, $$Otorgaste, según me han contado, la comisión del Rey a este hombre. Su propio tono traicionó la amargura de su rencor.$$, $$Estoy seguro de que no otorgaste la comisión del Rey a este hombre, dijo alegremente.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1618, $$Ha otorgado, según me han contado, la comisión del Rey a este hombre. Su propio tono traicionó la amargura de su rencor.$$, $$Su tono denunció la amargura de su resentimiento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1619, $$Ha otorgado, según me han contado, la comisión del Rey a este hombre. Su propio tono traicionó la amargura de su rencor.$$, $$Usted ha concedido, según tengo entendido, la autorización del rey al hombre por su valentía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1620, $$Era muy blanca, y mantuvo la mirada sobre sus manos dobladas.$$, $$Estaba triste y mantenía los ojos cerrados en todo momento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1621, $$Era muy blanca, y mantuvo la mirada sobre sus manos dobladas.$$, $$Estaba muy pálida y mantuvo sus ojos en sus manos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1622, $$Era muy blanca, y mantuvo la mirada sobre sus manos dobladas.$$, $$Ella era muy blanca porque solía vivir en un país frío.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1623, $$¡Así que te contaron sobre eso!$$, $$¡Entonces no te informaron sobre nuestra situación!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1624, $$¡Así que te contaron sobre eso!$$, $$¡Entonces te contaron sobre la situación difícil!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1625, $$¡Así que te contaron sobre eso!$$, $$¡Entonces te dijeron sobre eso!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1626, $$Se dio cuenta de que tal vez ella misma había provocado su enojo.$$, $$Estaba enojado porque ella siempre habla demasiado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1627, $$Se dio cuenta de que tal vez ella misma había provocado su enojo.$$, $$Él estaba muy feliz, así que ella no estaba preocupada por su enojo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1628, $$Se dio cuenta de que tal vez ella misma había provocado su enojo.$$, $$Ella pensó que tal vez pudo haber provocado su enojo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1629, $$Siempre estaré agradecido.$$, $$Te estaré eternamente agradecido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1630, $$Siempre estaré agradecido.$$, $$Estoy realmente feliz y agradecido por lo que hiciste hoy.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1631, $$Siempre estaré agradecido.$$, $$Estaré por siempre lleno de malicia y odio.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1632, $$No por su sobrina, no por su hija, no por su propia madre, olvidaría la sangre que cree que se le debe.$$, $$Él quería venganza más que cualquier otra cosa en el mundo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1633, $$No por su sobrina, no por su hija, no por su propia madre, renunciaría la sangre que cree que se le debe.$$, $$Él renunciaría a la sangre que se le debía si su madre se lo pedía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1634, $$No por su sobrina, no por su hija, no por su propia madre, olvidaría la sangre que cree que se le debe.$$, $$No renunciaría a la sangre que creía que le debía a su hija, a su madre o a su sobrina.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1635, $$Abeam con La Argentina, al otro lado del puerto, eran los edificios blancos de cara plana de esa imponente ciudad que descendía hasta la orilla del agua.$$, $$La Argentina llegó a una ciudad chica que estaba ubicada en una tierra yerma carente de vida.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1638, $$En lo mío no he hecho nada de lo que me avergüence, teniendo en cuenta la provocación que recibí. Su mirada vaciló, y cayó antes que la suya tan intensa.$$, $$No me avergüenzo de nada de lo que he hecho, teniendo en cuenta la provocación que he recibido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1646, $$Entonces solo fuiste un caballero desafortunado.$$, $$Fuiste desafortunado pero ahora tenés una situación mejor.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1647, $$El Capitán Bouchard descubrió su cabeza y se inclinó silenciosamente en un saludo, que ella devolvió sosegada y formalmente.$$, $$El Capitán Bouchard se inclinó silenciosamente porque era un hombre tranquilo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1648, $$El Capitán Bouchard descubrió su cabeza y se inclinó silenciosamente en un saludo, que ella devolvió sosegada y formalmente.$$, $$El Capitán Bouchard ignoró por completo su presencia y ella tampoco lo notó a él.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1649, $$El Capitán Bouchard descubrió su cabeza y se inclinó silenciosamente en un saludo, que ella devolvió sosegada y formalmente.$$, $$Ella respondió al saludo del Capitán Bouchard de una manera formal y tranquila.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1650, $$Había habido problemas con Rodríguez desde el momento del desembarco.$$, $$Hubo problemas con Rodríguez desde el aterrizaje.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1651, $$Había habido problemas con Rodríguez desde el momento del desembarco.$$, $$Hubo problemas con Rodríguez porque a nadie le gusta.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1652, $$Había habido problemas con Rodríguez desde el momento del desembarco.$$, $$No había problemas, todo estaba perfectamente bien.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1653, $$Mientras tanto, González estaba cada vez más impaciente.$$, $$González había estado esperando mucho tiempo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1654, $$Mientras tanto, González estaba cada vez más impaciente.$$, $$González estaba perdiendo la paciencia.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1655, $$Mientras tanto, González estaba cada vez más impaciente.$$, $$González estaba tranquilo y calmado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1656, $$El General San Martín fue sentencioso, cómo me consta que a menudo lo era.$$, $$No creo que el General San Martín fuera sentencioso, ¡era tan boludo!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1657, $$El San Martín fue sentencioso, cómo me consta que a menudo lo era.$$, $$Creo que el San Martín fue sentencioso, como solía serlo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
