  (1686, $$¡Sí! Grité en el coro de los bucaneros abajo, y uno o dos de ellos elaboraron esa afirmación.$$, $$Todos los bucaneros de la mayoría de los barcos son muy ruidosos cuando gritan al unísono.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1687, $$¡Sí! Grité en el coro de los bucaneros abajo, y uno o dos de ellos elaboraron esa afirmación.$$, $$Los corsarios fueron ruidosos cuando dijeron sí.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1689, $$En la cabina, se dejó caer en una silla y explotó, con una violencia completamente ajena a su naturaleza.$$, $$Se sentó en una silla de la cabina.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1690, $$En la cabina, se dejó caer en una silla y explotó, con una violencia completamente ajena a su naturaleza.$$, $$Él se sentó en una silla verde en la cabina.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1691, $$En la cabina, se dejó caer en una silla y explotó, con una violencia completamente ajena a su naturaleza.$$, $$Se sentó en el piso de la cabaña porque no había sillas disponibles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
