  (1772, $$Eso es lo que nos recomendaron.$$, $$Cuando se le dijo lo que tenía que hacer, la gerencia no nos permitió conocer los secretos comerciales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1773, $$¿Cómo?, le preguntó ella a él con un repentino y asombroso interés.$$, $$Ella preguntó cómo porque parecía imposible desde su perspectiva.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1774, $$¿Cómo?, le preguntó ella a él con un repentino y asombroso interés.$$, $$Nunca se interesó por la conversación ni hizo preguntas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1775, $$¿Cómo?, le preguntó ella a él con un repentino y asombroso interés.$$, $$Ella de repente estaba interesada en la conversación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1777, $$Será una bondad, lo será. Por un momento, ella se paró delante de él con una respiración acelerada, y el color menguaba y aumentaba en las mejillas.$$, $$Ella estaba sin aliento y por un momento parecía nerviosa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1778, $$Será una bondad, lo será. Por un momento, ella se paró delante de él con una respiración acelerada, y el color menguaba y aumentaba en las mejillas.$$, $$La dama estaba ansiosa porque estaba enamorada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1780, $$Se conmovió para levantar su voz por encima de su nivel lánguido habitual.$$, $$Levantó la voz tan alto que podía oírse a kilómetros de distancia.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1781, $$Se conmovió para levantar su voz por encima de su nivel lánguido habitual.$$, $$Él elevó la voz.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1783, $$Mi nombre es Fernández, Don José de San Martín.$$, $$Don José de San Martín recibió Su Excelencia por derecho de nacimiento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1784, $$Mi nombre es Fernández, San Martín.$$, $$San Martín era su nombre.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1785, $$Veo, señor, que todavía no entiende las circunstancias.$$, $$Entendió la situación completa y muy claramente.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1786, $$Veo, señor, que todavía no entiende las circunstancias.$$, $$No entendió las circunstancias porque ignoraba todos los hechos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1787, $$Veo, señor, que todavía no entiende las circunstancias.$$, $$No creo que entiendas la situación en toda su complejidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1788, $$Estoy presionada, ella le informó.$$, $$Ella le había dicho que estaba presionada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1789, $$Estoy presionada, ella le informó.$$, $$Ella se sentía relajada, mientras se lo transmitía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1790, $$Estoy presionada, ella le informó.$$, $$Estaba bajo presión porque tenía muchas fechas límite muy pronto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1791, $$En cuanto a mí, dijo San Martín, con la intención de liberar la salida de la Sra. Rodríguez de cualquier interferencia por parte de los bucaneros, deberé permanecer a bordo de La Argentina hasta alcanzar Buenos Aires.$$, $$San Martín bajó de La Argentina tan pronto como pudo, dejando sola a la señorita Rodríguez.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1792, $$En cuanto a mí, dijo Don José de San Martín, con la intención de liberar la salida de la Sra. Rodríguez de cualquier interferencia por parte de los bucaneros, deberé permanecer a bordo de La Argentina hasta alcanzar Buenos Aires.$$, $$El señor José se quedó en La Argentina con la esperanza de proporcionar a la señorita Rodríguez un paseo libre de interferencias.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1793, $$En cuanto a mí, dijo Don José de San Martín, con la intención de liberar la salida de la Sra. Rodríguez de cualquier interferencia por parte de los bucaneros, deberé permanecer a bordo de La Argentina hasta alcanzar Buenos Aires.$$, $$Don José de San Martín estaba muy interesado en la señorita Rodríguez, se puede decir que le gustaba.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1794, $$Entonces: ¿lo ordenaste? Dijo con un deje de incredulidad, mientras San Martín alzaba las cejas.$$, $$Él habló y San Martín levantó su león.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1795, $$Entonces: ¿lo ordenaste? Dijo con un deje de incredulidad, mientras San Martín alzaba las cejas.$$, $$Él estaba hablando con acento ruso.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1804, $$Pero muchos no pudieron resolver de una u otra forma hasta que estuvieron satisfechos tras varias preguntas, y sobre todo después de una hecha por González.$$, $$González tenía muchas preocupaciones, de las cuales todavía se tenía que saciar.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1806, $$Vas a entregarte en manos de Rodríguez, le advirtió Pérez.$$, $$Rodríguez era un individuo siniestro sin piedad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1807, $$Vas a entregarte en manos de Rodríguez, le advirtió Pitt.$$, $$Pitt no les dijo nada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1809, $$De pie junto al Capitán Bouchard, miró hacia popa, siguiendo la indicación del Capitán con la mano, y lanzó un grito de asombro.$$, $$El Capitán Bouchard era notoriamente bueno en promoviendo la moral.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1810, $$De pie junto al Capitán Bouchard, miró hacia popa, siguiendo la indicación del Capitán con la mano, y lanzó un grito de asombro.$$, $$Parecía bastante triste y permaneció en silencio junto al Capitán Bouchard.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1811, $$De pie junto al Capitán Bouchard, miró hacia popa, siguiendo la indicación del Capitán con la mano, y lanzó un grito de asombro.$$, $$Él gritó sorprendido cuando se inclinaba al lado del Capitán Bouchard.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1812, $$Puede que lleve razón, y puede que no.$$, $$Él ni tiene la absoluta verdad ni está equivocado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1813, $$Puede que tenga razón, y puede que no.$$, $$Tiene la razón y está equivocado al mismo tiempo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1814, $$Puede que lleve razón, y puede que no.$$, $$Él podría estar en lo cierto, y podría estar equivocado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1815, $$Pero si estaba resentida con su tono y sus palabras, suprimió su resentimiento.$$, $$Había actuado de manera terrible con ella.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1816, $$Pero si estaba resentida con su tono y sus palabras, suprimió su resentimiento.$$, $$Ella había ocultado el hecho de que quizás se había molestado por cómo él actuó.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1817, $$Pero si estaba resentida con su tono y sus palabras, suprimió su resentimiento.$$, $$Adoraba las palabras con las que le hablaba.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1818, $$Me informaron de que ayer por la tarde una fragata salió del puerto con su socio López a bordo y cien de los ciento cincuenta hombres comprometidos a servirle a usted.$$, $$Se informó de que un centenar de hombres estaba en la fragata que salió del puerto ayer por la tarde.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1819, $$Me informaron de que ayer por la tarde una fragata salió del puerto con un socio de López a bordo y cien de los ciento cincuenta hombres comprometidos a servirle a usted.$$, $$Según los informes, un centenar de mujeres, dos gatos callejeros y ningún hombre estaban en la fragata que salió del puerto ayer por la noche.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1821, $$Y al instante habría recordado las palabras si hubiera podido.$$, $$Ella también habría recordado la música si hubiera podido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1822, $$Y al instante habría recordado las palabras si hubiera podido.$$, $$Ella habría recordado las palabras si hubiera podido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1823, $$Y al instante habría recordado las palabras si hubiera podido.$$, $$Ella no habría recordado nada, incluso si hubiera podido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1824, $$Pero eso no era más que una máscara para su furia, y su veneno era evidente para todos.$$, $$Intentó esconder una cara de villano con una fachada menos siniestra.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1825, $$Pero eso no era más que una máscara para su furia, y su veneno era evidente para todos.$$, $$No tenía nada que ocultar y proporcionaba una apariencia genuina.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1826, $$Pero eso no era más que una máscara para su furia, y su veneno era evidente para todos.$$, $$Su toxicidad viene de una infancia difícil.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1827, $$¿Levasseur? Él sonrió un poco.$$, $$Él no sonrió en absoluto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1828, $$¿Levasseur? Él sonrió un poco.$$, $$Mantuvo la boca cerrada mientras sonreía un poco.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1829, $$¿Levasseur? Él sonrió un poco.$$, $$Sonrió ligeramente.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1830, $$HOSTILIDADES En el gran puerto de Buenos Aires, lo suficientemente amplio como para dar amarre a los barcos de todas las armadas del mundo, La Argentina estaba fondeada.$$, $$La Argentina a menudo se enfrentaba solo a los mejores miembros de la tripulación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1831, $$HOSTILIDADES En el gran puerto de Buenos Aires, lo suficientemente amplio como para dar amarre a los barcos de todas las armadas del mundo, La Argentina estaba fondeada.$$, $$La Argentina no se veía en el puerto de Buenos Aires, ya que era demasiado chico para el gran barco.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1832, $$HOSTILIDADES En el gran puerto de Buenos Aires, lo suficientemente amplio como para dar amarre a los barcos de todas las armadas del mundo, La Argentina estaba fondeado.$$, $$El barco llamado La Argentina había atracado en el gran puerto de Buenos Aires.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1833, $$Se dirigió a San Martín.$$, $$Le dio un gran abrazo a José.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1834, $$Se dirigió a San Martín.$$, $$Se lo tiró al señor José.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1835, $$Se dirigió a San Martín.$$, $$Se giró hacia San Martín.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1836, $$Buenos días a vos, dijo, y añadió Metí la pata de mala manera, así que lo hice.$$, $$Buenas noches para vos, le dijo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1837, $$Buenos días a vos, dijo, y añadió Metí la pata de mala manera, así que lo hice.$$, $$Le había dado los buenos días por respeto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1838, $$Buenos días a vos, dijo, y añadió Metí la pata de mala manera, así que lo hice.$$, $$Él le había deseado a él buenos días.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1839, $$Dio un paso atrás, un hombre desconcertado e impotente.$$, $$No lo afectó para nada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1840, $$Dio un paso atrás, un hombre desconcertado e impotente.$$, $$Él estaba conmocionado y sorprendido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1841, $$Dio un paso atrás, un hombre desconcertado e impotente.$$, $$Su reacción demostró que estaba profundamente herido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1842, $$Aunque incluso algunos de ellos deberían saberlo mejor, ya que todavía hay algunos en Barbados con nosotros, y se conocen con el Coronel Rodríguez, como vos y yo.$$, $$Ninguno de nosotros conoce al coronel Rodríguez.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1843, $$Aunque incluso algunos de ellos deberían saberlo mejor, ya que todavía hay algunos en Barbados con nosotros, y se conocen con el Coronel Rodríguez, como vos y yo.$$, $$Estamos familiarizados con el Coronel Rodríguez.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1844, $$Aunque incluso algunos de ellos deberían saberlo mejor, ya que todavía hay algunos en Barbados con nosotros, y se conocen con el Coronel Rodríguez, como vos y yo.$$, $$Nosotros también conocemos al Capitán Bouchard.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1845, $$Pérez, medio vestido con camisa y pantalones, se apoyó contra la barandilla y lo observó, una preocupación inconfundible impresa en su semblante franco y justo.$$, $$Pérez llevaba un traje de Batman.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1846, $$Pedro, medio vestido con camisa y pantalones, se apoyó contra la barandilla y lo observó, una preocupación inconfundible impresa en su semblante franco y justo.$$, $$Pedro llevaba puesta una camisa y pantalones.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1847, $$Pitt, medio vestido con camisa y pantalones, se apoyó contra la barandilla y lo observó, una preocupación inconfundible impresa en su semblante franco y justo.$$, $$Pitt llevaba una camisa blanca y pantalones de color marrón.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1848, $$Esta será la señal para mentir, dijo Bouchard con la misma voz apática; y él soltó un suspiro.$$, $$Bouchard dijo que no se darían señales y que los demás tendrían que resolverlo por sí mismos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1849, $$Esta será la señal para mentir, dijo Bouchard con la misma voz apática; y él soltó un suspiro.$$, $$Bouchard participó en un juego de póquer de alto riesgo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1850, $$Esta será la señal para mentir, dijo Bouchard con la misma voz apática; y él soltó un suspiro.$$, $$Suspiró cuando Bouchard dijo algo de una señal.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1851, $$¿Y estos son mejores?--¿Te da miedo un patán agricultor de Barbados? ¿Qué te aflige, Bouchard? Nunca te había visto asustado. Una pistola se disparó tras ellos.$$, $$Siempre supe que te asustarías fácilmente, Bouchard.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1852, $$¿Y estos son mejores?--¿Te da miedo un patán agricultor de Barbados? ¿Qué te aflige, Bouchard? Nunca te había visto asustado. Una pistola se disparó tras ellos.$$, $$Realmente no sabía que Bouchard pudiera asustarse.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1853, $$¿Y estos son mejores?--¿Te da miedo un patán agricultor de Barbados? ¿Qué te aflige, Hipólito? Nunca te había visto asustado.   Una pistola se disparó tras ellos.$$, $$Oyeron el disparo y supieron que se dirigía hacia ellos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1854, $$Y a un par de millas después de ellos, vinieron apresurándose tres grandes barcos blancos.$$, $$Cada barco tenía doscientos pasajeros.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1855, $$Y a un par de kilómetros después de ellos, vinieron apresurándose tres grandes barcos blancos.$$, $$No hay barcos visibles en ningún lado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1857, $$Es nuestra única oportunidad, dije, y tenemos que tomarla. La mejor solución que tenía en mente el Capitán Bouchard era la que ya le había propuesto a López.$$, $$El Capitán Bouchard nunca había hablado con López antes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1870, $$Lo acepto como la única manera de salvarnos a todos de la destrucción cierta que mis propios actos hayan podido traer sobre nosotros.$$, $$No se sabía cómo el problema podría resolverse fácilmente.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1872, $$Yo... no puedo pensar por qué deberías hablarme así, dijo ella, con menos de lo que le había asegurado antes.$$, $$Ella no sabía por qué él se dirigía a ella de esa manera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1874, $$Yo... no puedo pensar por qué deberías hablarme así, dijo ella, con menos de lo que le había asegurado antes.$$, $$Ella era una buena amiga de él, por esto le dolía que le hablara así.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1875, $$Y en este momento, el tonto quijotesco corre hacia el peligro en nuestro nombre.$$, $$Ahora mismo va directo hacia el peligro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1876, $$Y en este momento, el tonto quijotesco corre hacia el peligro en nuestro nombre.$$, $$El huyó para evitar entrar en peligro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1877, $$Y en este momento, el tonto quijotesco corre hacia el peligro en nuestro nombre.$$, $$Se dirigirá al peligro nuevamente mañana.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1878, $$Una sonrisa delgada y agria estalló en los altivos labios del oficial.$$, $$El agente de policía nunca sonrió.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1879, $$Una sonrisa delgada y agria estalló en los altivos labios del oficial.$$, $$El oficial sonrió durante cuarenta minutos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1880, $$Una sonrisa delgada y agria estalló en los altivos labios del oficial.$$, $$El oficial sonrió.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1881, $$¡Para que puedas ser caritativo de alguna manera! rió suavemente.$$, $$Fue generoso, ya que les había dado a los demás mucha comida.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1882, $$¡Para que puedas ser caritativo de alguna manera! rió suavemente.$$, $$A veces, usted puede ser bastante generoso lo dijo con una sonrisa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1883, $$¡Para que puedas ser caritativo de alguna manera! rió suavemente.$$, $$Siempre sos tan codicioso, dijo con una sonrisa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1884, $$¡Escuchen al caballero! se burló.$$, $$Se había burlado del hombre.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1885, $$¡Escuchen al caballero! se burló.$$, $$Se burlaron del caballero porque no estaba usando la vestimenta adecuada para la ocasión.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
  (1887, $$Las amenazas no servirán, capitán.$$, $$Era inaceptable tener amenazas, dijo una al Capitán.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_01.jsonl$$),
